analyze.mjs.text:
// Classifies a set of CORS probe results (real HTTP responses, collected by
// probe.mjs's live network requests or pasted in by hand) into named CORS
// misconfiguration patterns.
//
// Pure function, no I/O, no network -- this is the module both the CLI
// (check.mjs, which fetches for real) and the browser page (index.html,
// which can only ever analyse a payload someone already fetched) import, so
// the classification logic exists exactly once.
//
// Why the browser can never fetch this itself: `Origin` is a forbidden
// request-header name under the WHATWG Fetch spec, so `fetch()`/`XHR` inside
// a browser tab cannot set it to anything but the page's own origin --
// that restriction is part of what CORS protects, and no page running this
// checker can spoof around it. Only a non-browser HTTP client (this CLI,
// curl, Corsy, etc.) can send the crafted Origin headers these probes need.
// See README.md and index.html's FAQ for the fuller explanation.
//
// The four probes and what each one tests, in the terms PortSwigger's Web
// Security Academy "CORS" material and the wider bug-bounty literature use:
//
//   reflect        An origin with no relationship to the target at all
//                   ("https://cors-probe-<random>.invalid"). If the server's
//                   Access-Control-Allow-Origin echoes it back verbatim, the
//                   server trusts *any* origin -- the broadest possible
//                   misconfiguration.
//   null-origin    Origin: null. A sandboxed iframe or a `data:` URI sends
//                   this automatically, so an attacker-controlled page can
//                   trigger it with no special setup. A server that reflects
//                   `null` is trusting an origin any attacker can produce.
//   prefix-match   Origin = the target's own origin plus an attacker-chosen
//                   suffix ("https://target.example.com.attacker.invalid").
//                   Passes a naive `origin.startsWith(allowedOrigin)` check.
//   suffix-match   Origin = an attacker-chosen prefix plus the target's
//                   hostname ("https://evil-target.example.com"). Passes a
//                   naive `origin.endsWith(allowedHost)` or
//                   `origin.includes(allowedHost)` check with no dot-boundary
//                   anchor.
//   same-origin    Origin = the target's own origin. This one is not an
//                   attack, and a server echoing it back is never a finding
//                   on its own -- that is the correct, healthy answer. It
//                   exists so the Vary: Origin check below can fire on a
//                   server whose allow-list *works*, which is the only
//                   population that check was ever about. See the note on
//                   `missing-vary-origin`.
//
// A server correctly validating against an explicit allow-list should never
// reflect any of the four attack origins back -- rejecting them is the
// expected, healthy result and is why a clean report says so rather than
// just staying silent.

export const PROBE_LABELS = [
  'baseline', 'reflect', 'null-origin', 'prefix-match', 'suffix-match', 'same-origin',
];

function norm(value) {
  return typeof value === 'string' ? value.trim() : null;
}

function isTrue(value) {
  return typeof value === 'string' && value.trim().toLowerCase() === 'true';
}

function acao(probe) {
  return norm(probe?.headers?.['access-control-allow-origin']);
}

function acac(probe) {
  return norm(probe?.headers?.['access-control-allow-credentials']);
}

function vary(probe) {
  return norm(probe?.headers?.vary);
}

function reflectsRequestOrigin(probe) {
  const value = acao(probe);
  return value !== null && probe.requestOrigin !== null && value === probe.requestOrigin;
}

function byLabel(probes) {
  const map = new Map();
  for (const probe of probes || []) {
    if (probe && typeof probe.label === 'string') map.set(probe.label, probe);
  }
  return map;
}

/**
 * @param {string} target - the URL that was probed (for display only)
 * @param {Array<{label: string, requestOrigin: string|null, ok: boolean,
 *   status: number|null, headers: Record<string,string|null>, error: string|null}>} probes
 * @returns {{
 *   target: string, probes: object[], findings: object[],
 *   dangerCount: number, noticeCount: number, ok: boolean, incomplete: boolean,
 * }}
 */
export function buildReport(target, probes) {
  const list = Array.isArray(probes) ? probes : [];
  const map = byLabel(list);
  const findings = [];

  const failed = list.filter((p) => p && p.ok === false).map((p) => p.label);
  const incomplete = failed.length > 0;

  const reflect = map.get('reflect');
  if (reflect && reflect.ok !== false && reflectsRequestOrigin(reflect)) {
    findings.push({
      id: 'reflects-arbitrary-origin',
      severity: 'danger',
      title: 'Reflects an unrelated origin',
      detail:
        `Sent Origin: ${reflect.requestOrigin} (an origin with no relationship to this site) ` +
        `and the response echoed it back verbatim in Access-Control-Allow-Origin. This server ` +
        `trusts any origin at all, not a specific allow-list.` +
        (isTrue(acac(reflect))
          ? ' Access-Control-Allow-Credentials is also true, so any site on the web can make ' +
            "authenticated requests as a logged-in visitor and read the response."
          : ''),
      probeLabel: 'reflect',
      requestOrigin: reflect.requestOrigin,
      evidenceHeader: `access-control-allow-origin: ${acao(reflect)}`,
    });
  }

  const nullOrigin = map.get('null-origin');
  if (nullOrigin && nullOrigin.ok !== false && acao(nullOrigin) === 'null') {
    findings.push({
      id: 'accepts-null-origin',
      severity: 'danger',
      title: 'Accepts Origin: null',
      detail:
        'Access-Control-Allow-Origin: null trusts the literal string "null" as an origin. ' +
        'A sandboxed iframe or a data: URI sends Origin: null automatically, so any attacker-' +
        'controlled page can produce this origin with no domain of their own.',
      probeLabel: 'null-origin',
      requestOrigin: 'null',
      evidenceHeader: `access-control-allow-origin: ${acao(nullOrigin)}`,
    });
  }

  for (const label of ['prefix-match', 'suffix-match']) {
    const probe = map.get(label);
    if (probe && probe.ok !== false && reflectsRequestOrigin(probe)) {
      const kind = label === 'prefix-match' ? 'startsWith' : 'endsWith/includes';
      findings.push({
        id: 'unanchored-origin-match',
        severity: 'danger',
        title: `Origin allow-list looks unanchored (${label})`,
        detail:
          `Sent Origin: ${probe.requestOrigin}, an attacker-registrable domain built to pass a ` +
          `naive \`${kind}\` string check against this site's real origin/hostname, and the ` +
          `response reflected it back. The allow-list check needs an exact match or a properly ` +
          `dot-anchored subdomain check, not a substring test.`,
        probeLabel: label,
        requestOrigin: probe.requestOrigin,
        evidenceHeader: `access-control-allow-origin: ${acao(probe)}`,
      });
    }
  }

  const wildcardWithCreds = list.find(
    (p) => p && p.ok !== false && acao(p) === '*' && isTrue(acac(p)),
  );
  if (wildcardWithCreds) {
    findings.push({
      id: 'wildcard-with-credentials',
      severity: 'notice',
      title: 'Wildcard origin with credentials allowed',
      detail:
        'Access-Control-Allow-Origin: * together with Access-Control-Allow-Credentials: true is ' +
        'invalid under the Fetch spec, and current browsers refuse to expose a credentialed ' +
        'response in this case -- so this is unlikely to be directly exploitable through a ' +
        'browser today. It still signals a copy-pasted or overly permissive CORS policy worth ' +
        'reviewing, and a non-browser HTTP client would not enforce the block.',
      probeLabel: wildcardWithCreds.label,
      requestOrigin: wildcardWithCreds.requestOrigin,
      evidenceHeader: `access-control-allow-origin: * ; access-control-allow-credentials: ${acac(wildcardWithCreds)}`,
    });
  }

  // Vary: Origin. This used to look only at the `reflect` probe, which meant
  // it could only ever fire on a server that had *already* been flagged as
  // trusting arbitrary origins -- so for the population it actually matters
  // for (a working allow-list that echoes each permitted origin back and
  // forgets to say the response varies by it, the ordinary shape behind CORS
  // cache poisoning) the check was dead. The `same-origin` probe exists to
  // give it a case it can see.
  //
  // The discrimination that keeps this from crying wolf is `baseline`: a
  // server that sends the same Access-Control-Allow-Origin with no Origin
  // header at all is answering statically, and a cache cannot confuse a
  // response that is identical for everybody. Only a header that changes
  // with the request needs Vary.
  const baseline = map.get('baseline');
  const staticAcao =
    baseline && baseline.ok !== false ? acao(baseline) : null;
  const varyCandidate = ['reflect', 'same-origin', 'null-origin', 'prefix-match', 'suffix-match']
    .map((label) => map.get(label))
    .find(
      (probe) =>
        probe &&
        probe.ok !== false &&
        reflectsRequestOrigin(probe) &&
        acao(probe) !== staticAcao &&
        !(vary(probe) || '').toLowerCase().includes('origin'),
    );
  if (varyCandidate) {
    findings.push({
      id: 'missing-vary-origin',
      severity: 'notice',
      title: 'Dynamic origin with no Vary: Origin',
      detail:
        'The response reflects the request Origin back but does not send Vary: Origin. A shared ' +
        'or intermediary cache that does not know the response varies by Origin can serve one ' +
        "visitor's CORS-permissive response to a different origin's request." +
        (varyCandidate.label === 'same-origin'
          ? ' This one is worth reading carefully: the allow-list itself is behaving correctly ' +
            'here -- it echoed back an origin it should echo back. The risk is the caching layer ' +
            'in front of it, not the check behind it.'
          : ''),
      probeLabel: varyCandidate.label,
      requestOrigin: varyCandidate.requestOrigin,
      evidenceHeader: `vary: ${vary(varyCandidate) ?? '(not set)'}`,
    });
  }

  const dangerCount = findings.filter((f) => f.severity === 'danger').length;
  const noticeCount = findings.filter((f) => f.severity === 'notice').length;

  return {
    target,
    probes: list.map((p) => ({
      label: p.label,
      requestOrigin: p.requestOrigin ?? null,
      ok: p.ok !== false,
      status: p.status ?? null,
      headers: p.headers ?? {},
      error: p.error ?? null,
    })),
    findings,
    dangerCount,
    noticeCount,
    ok: !incomplete && dangerCount === 0,
    incomplete,
    failedProbes: failed,
  };
}

check.mjs.text:
#!/usr/bin/env node
// CLI: sends six real GET requests to a URL you name, each with a
// different Origin header, and reports which CORS misconfiguration
// patterns the response headers show. Your machine, your network -- no
// request goes through this portfolio or anywhere but the URL you pass.
//
//   node check.mjs <url> [--json] [--timeout <ms>]
//
// Only point this at a system you own or are authorised to test. This
// sends ordinary, unauthenticated GET requests -- nothing here bypasses
// authentication, reads protected data, or does anything a browser
// wouldn't also do by visiting the URL -- but treat it the same as you
// would curl or any other request tool aimed at someone else's server.
//
// Exit code 0 when every probe completed and none is a "danger"-severity
// finding; 1 when at least one danger finding is present or a probe
// failed to complete (network error, timeout, bad URL).

import { runProbes } from './probe.mjs';
import { buildReport } from './analyze.mjs';

function formatText(report) {
  const lines = [];
  lines.push(`Target: ${report.target}`);
  lines.push('');

  for (const probe of report.probes) {
    const origin = probe.requestOrigin ?? '(no Origin header sent)';
    if (!probe.ok) {
      lines.push(`  [${probe.label}] Origin: ${origin} -- request failed: ${probe.error}`);
      continue;
    }
    const acao = probe.headers['access-control-allow-origin'] ?? '(not set)';
    const acac = probe.headers['access-control-allow-credentials'] ?? '(not set)';
    lines.push(`  [${probe.label}] Origin: ${origin}  ->  status ${probe.status}, ACAO: ${acao}, ACAC: ${acac}`);
  }
  lines.push('');

  if (report.incomplete) {
    lines.push(`${report.failedProbes.length} probe(s) did not complete: ${report.failedProbes.join(', ')}. Re-run once the target is reachable.`);
    lines.push('');
  }

  if (report.findings.length === 0) {
    lines.push(report.incomplete
      ? 'No misconfiguration found in the probes that did complete, but the run is not complete -- see above.'
      : 'None of the four dangerous CORS patterns this tool checks for were found.');
  } else {
    for (const f of report.findings) {
      const mark = f.severity === 'danger' ? '!!' : '--';
      lines.push(`${mark} [${f.severity.toUpperCase()}] ${f.title}`);
      lines.push(`     ${f.detail}`);
      lines.push(`     evidence: ${f.evidenceHeader}`);
      lines.push('');
    }
  }

  lines.push(
    'This is evidence from the responses above, not a full security assessment -- ' +
      'see README.md for what this tool does and does not check.',
  );
  return lines.join('\n');
}

function parseArgs(argv) {
  const args = { target: null, json: false, timeoutMs: undefined };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--json') args.json = true;
    else if (argv[i] === '--timeout') args.timeoutMs = Number(argv[++i]);
    else if (!args.target && !argv[i].startsWith('--')) args.target = argv[i];
  }
  return args;
}

/** Pure orchestration: given a probe function (real network, or a stub in
 * tests), fetch and classify. Kept separate from main() so tests can inject
 * a fake `probeFn` instead of hitting the network. */
export async function runCheck(target, { probeFn = runProbes, timeoutMs } = {}) {
  const probes = await probeFn(target, timeoutMs ? { timeoutMs } : {});
  return buildReport(target, probes);
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.target) {
    console.error('Usage: node check.mjs <url> [--json] [--timeout <ms>]');
    process.exit(2);
  }
  try {
    // eslint-disable-next-line no-new
    new URL(args.target);
  } catch {
    console.error(`Not a valid URL: ${args.target}`);
    process.exit(2);
  }

  const report = await runCheck(args.target, { timeoutMs: args.timeoutMs });

  if (args.json) {
    console.log(JSON.stringify({ target: report.target, probes: report.probes }, null, 2));
  } else {
    console.log(formatText(report));
  }
  process.exit(report.ok ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

probe.mjs.text:
// Sends the real HTTP requests this check depends on: six GET requests to
// one target URL, each with a different (or absent) Origin request header,
// reading back only the three CORS response headers that matter. Node's
// built-in http/https clients are used deliberately, not fetch(): fetch()
// enforces the same forbidden-header-name rule browsers do for `Origin` in
// some runtimes, and the whole point of a CLI here is that it is not a
// browser and is not bound by that restriction -- the same reason curl,
// Corsy, and every other CORS-testing tool are standalone clients rather
// than browser scripts.
//
// This module only ever talks to the one target URL a caller names. It
// makes no other network call, reads no local files, and sends nothing
// anywhere else.

import { request as httpRequest } from 'node:http';
import { request as httpsRequest } from 'node:https';
import { randomBytes } from 'node:crypto';

const DEFAULT_TIMEOUT_MS = 10_000;
const USER_AGENT =
  'cors-misconfig-check/1 (+https://duncan-haywood.github.io/monorepo-projects/cors-misconfig-check/)';

function headerValue(headers, name) {
  const value = headers[name.toLowerCase()];
  if (value == null) return null;
  return Array.isArray(value) ? value.join(', ') : String(value);
}

/**
 * One GET request to `targetUrl` with `originHeader` set as the Origin
 * request header (or omitted entirely when `originHeader` is null).
 * Resolves rather than rejects on any failure so a caller running several of
 * these never needs a try/catch per probe.
 */
export function sendProbe(targetUrl, originHeader, { timeoutMs = DEFAULT_TIMEOUT_MS } = {}) {
  return new Promise((resolve) => {
    let parsed;
    try {
      parsed = new URL(targetUrl);
    } catch (err) {
      resolve({ ok: false, status: null, headers: {}, error: `invalid URL: ${err.message}` });
      return;
    }
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      resolve({ ok: false, status: null, headers: {}, error: `unsupported scheme: ${parsed.protocol}` });
      return;
    }

    const requester = parsed.protocol === 'https:' ? httpsRequest : httpRequest;
    const headers = { 'user-agent': USER_AGENT, accept: '*/*' };
    if (originHeader !== null) headers.origin = originHeader;

    let settled = false;
    const finish = (result) => {
      if (settled) return;
      settled = true;
      resolve(result);
    };

    const req = requester(
      parsed,
      { method: 'GET', headers, timeout: timeoutMs },
      (res) => {
        res.on('data', () => {}); // headers are all this check needs; drain and discard the body
        res.on('end', () => {
          finish({
            ok: true,
            status: res.statusCode ?? null,
            headers: {
              'access-control-allow-origin': headerValue(res.headers, 'access-control-allow-origin'),
              'access-control-allow-credentials': headerValue(res.headers, 'access-control-allow-credentials'),
              vary: headerValue(res.headers, 'vary'),
            },
            error: null,
          });
        });
        res.on('error', (err) => finish({ ok: false, status: res.statusCode ?? null, headers: {}, error: err.message }));
      },
    );
    req.on('timeout', () => req.destroy(new Error('timed out')));
    req.on('error', (err) => finish({ ok: false, status: null, headers: {}, error: err.message }));
    req.end();
  });
}

/**
 * The six (label, Origin header) pairs this check always sends, derived
 * from the target so the prefix/suffix probes are meaningful for that exact
 * host. `randomOrigin` is injectable so tests get a fixed value instead of
 * a fresh random one every run.
 *
 * `same-origin` is the odd one out: it sends the target's own origin, which
 * is not an attack and is never a finding by itself. It is what lets the
 * Vary: Origin check in analyze.mjs see a server whose allow-list works --
 * without it that check could only fire on a server already flagged for
 * trusting arbitrary origins.
 */
export function buildProbeSet(targetUrl, { randomOrigin } = {}) {
  const parsed = new URL(targetUrl);
  const targetOrigin = parsed.origin;
  const hostname = parsed.hostname;
  const nonce = randomOrigin ?? `https://cors-probe-${randomBytes(6).toString('hex')}.invalid`;

  return [
    { label: 'baseline', requestOrigin: null },
    { label: 'reflect', requestOrigin: nonce },
    { label: 'null-origin', requestOrigin: 'null' },
    { label: 'prefix-match', requestOrigin: `${targetOrigin}.attacker-controlled.invalid` },
    { label: 'suffix-match', requestOrigin: `https://evil-${hostname}` },
    { label: 'same-origin', requestOrigin: targetOrigin },
  ];
}

/**
 * Runs the full probe set against `targetUrl` and returns the raw results
 * (same shape `analyze.mjs`'s `buildReport` expects), run in parallel since
 * each probe is an independent, read-only GET to the same URL.
 */
export async function runProbes(targetUrl, opts = {}) {
  const set = buildProbeSet(targetUrl, opts);
  const results = await Promise.all(
    set.map(async ({ label, requestOrigin }) => ({
      label,
      requestOrigin,
      ...(await sendProbe(targetUrl, requestOrigin, opts)),
    })),
  );
  return results;
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// target URL, the pasted probe JSON, or anything about what was checked --
// that is exactly the kind of thing that must not be transmitted anywhere,
// and this tool never reads it off the visitor's machine either.

const STORAGE_KEY = 'cors-misconfig-check-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'check_run') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten, which is the defect this change exists to fix.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
